"Anyone remember why the sky is a portal?":"Emlékszik valaki, miért portál az ég?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Azt mondják, ha beugrasz az aknába, az ellenségnél bukkansz fel. Nem tesztelem.",
"The Swarm painted their visors red again. Show-offs.":"Megint vörösre festették a szemellenzőiket a Raj tagjai. Nagyzoló alakok.",
"Ore, ore… when do we get some oil?":"Érc, érc… mikor kapunk végre egy kis olajat?",
"I dreamt I was a toaster. It was peaceful.":"Azt álmodtam, hogy kenyérpirító vagyok. Nyugodt volt.",
"Quiet. Too quiet.":"Csend van. Túl nagy a csend.",
