"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Üdv a meteoron! Te a Konzorcium harci robotja vagy. Nézz körül az egérrel, és menj: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: koppints a Shiftre — ugrás, tartsd a Shiftet — repülés. Az energia a talajon töltődik.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Lőj — bal egérgomb. Célzás — jobb egérgomb: pontosabb, nagyítással. Adj le pár lövést.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Újratöltés — R. A golyók közepes távolságban, 20–50 méteren hatnak a legjobban.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rakéta — Q. Harckocsik és épületek ellen. Lőj ki egy rakétát.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Felül a stratéga feladata látható. Fuss a zöld nyilak mentén: az útvonalon sprintelsz. Foglalj el egy pontot — maradj a jeladó közelében.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Az osztagod fedez téged: a portréik és az életerejük balra láthatók. Ha lemaradnak, megkérnek, hogy várj.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — gyors egységváltás a harc elhagyása nélkül: ugrás az osztagba vagy a harcokhoz legközelebbi harckocsiba. Próbáld ki.",
"Next to a tank or turret press E to take control. Or just carry on.":"Tank vagy lövegtorony mellett nyomd meg az E-t az irányításához. Vagy csak menj tovább.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Most jöhet a stratégia. Koppints a jobb felső sarokban a „◩ Stratégia” gombra — felülnézet a csatamezőről.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Most jöhet a stratégia. Nyomd meg a(z) {0} gombot (vagy a bal felső „◩ Stratégia” gombot) — felülnézet a csatamezőről.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Stratégiában a Kalauz segít: a felső ablak megmondja, mit tegyél, a keret mutatja a gombot, a gyűrű pedig a helyet a térképen. Teljesítsd három tanácsát.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Jelölj ki egy osztagot, és koppints a zöld „▶ Átvétel” gombra — újra harcba szállsz az adott harcosként. Amíg te lősz, az MI-stratéga vezényli a sereget.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Jelölj ki egy osztagot, és nyomd meg a(z) {0} gombot vagy a zöld „▶ Átvétel” gombot — újra harcba szállsz az adott bakaként (kijelölés nélkül a sajátodként). Amíg te lősz, az MI-stratéga vezényli a sereget.",
