"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Csak a mérnök épít. Ha nincs mérnök kijelölve, a gomb kiválasztja a legközelebbi szabadot, és elindítja a tervrajzot; utána bal egérgomb a helyre.",
