"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"Be — magától építi a bázist, katonákat rendel és parancsokat ad (a te parancsaid előnyt élveznek). Ki — mindent te csinálsz.",
"Auto-build on: the strategist builds the base with builders":"Automatikus építés be: a stratéga mérnökökkel építi a bázist",
