"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Aztán kattints (koppints) a földre: mennek és közben lőnek. Ellenségre — megtámadják. Ugyanaz, mint a jobb egérgomb.",
"Run":"Futás",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Aztán kattints (koppints) a földre: futnak, harcba nem bocsátkozva. Ugyanaz, mint a dupla jobb egérgomb.",
