"Run back to the HQ (or nearest outpost) without engaging.":"Futás vissza a főhadiszállásra (vagy a legközelebbi előőrsre), harc nélkül.",
"Squads jet up through the dome portal and land at the enemy.":"Az osztagok repülőcsomaggal felszállnak, átmennek a kupola portálján, és az ellenségnél landolnak.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Irányítsd te magad a kijelölt bakát, harckocsit vagy lövegtornyot. Ugyanez a billentyű csatában visszavisz a stratégiába.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 baka: rohamozó, nehézfegyveres, rakétás, szanitéc.",
