"Fast flying gunner, good against infantry.":"Gyors repülő lövész, jó gyalogság ellen.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Elit osztag erős repülőcsomaggal — légi deszantot hajthat végre a kupolán át.",
"A lone railgun sniper.":"Magányos mesterlövész sínágyúval.",
