"New in v6.2":"Újdonságok a v6.2-ben",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Új érclook: az érerek izzó smaragdzöld csiszolt kristályok fekete bazalton, szikrákkal és zöld párával; a kitermelő hatszögletű talapzat méhsejtkupolával és rácsos toronnyal, tetején zöld jelzőfény (csík és zászló csapatszínben)",
"New in v6.1":"Újdonságok a v6.1-ben",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Kedvenc osztály, mint a Battlefieldben (U, számok halál után): ha elérhető, ebbe születsz újra",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Járművek belső nézetből (V — kívülről/fülkéből); enyhe célzássegéd — a Beállításokban",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Könnyű kijutás a Magból: Szóköz — az aknához, B — kapszula a felszínre; a képességhatások halálkor nullázódnak",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Végtelen fejlődés: tábornokok és Marsall ★, karrierszintek, fegyvermesterség és kiegészítők, érmek, napi szerződések — Karrier képernyő",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Stratégia: sima görgős zoom, ikonok és feliratok az egységek fölött (Alt — mind), Csapatok / Épületek panel balra",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"jobb egérgomb — mozgás harccal, dupla jobb egérgomb — menet menet közbeni tüzeléssel; ritka parancsok a „További parancsok ▾” alatt; nincsenek duplikált gombok",
"New in v6":"Újdonságok a v6-ban",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Lövészjáték-szintű fegyverek: azonnali találatú golyók, 720 lövés/perces gépkarabély, géppuska, torkolattűz-rúgás, célzás jobb egérgombbal, tárak és R újratöltés, találatjelzők",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Nehezebb gravitáció, élénk jetpack, kitörés Z-vel vagy dupla jetpackkel a levegőben; egységváltáskor a fegyver már nem repül veled",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Mérnökök: jelölj ki egy mérnököt, válassz épületet, tedd le a tervrajzot; kitermelők az ércereken; kattints az „ÉRC”-re: látod a bevétel forrását és a gyorsítás módját",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"A szürke gombok megnyomhatók — megmutatjuk az okot és a megoldást; nagyobb gombok, „Folyamatban\" sáv, „▶ Birtokba vétel\", a Tab az egyetlen módváltó billentyű",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Stratégiai kamera ugrálás és átfordulás nélkül, zoom a kurzorhoz, húzható minitérkép",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Új harcjárművek: „Jackal\" portyázó, „Grad\" sorozatvető (önvezérelt rakéták), „Hammer\" aknavető; a Raj kapja a „Wasp\", „Hive\", „Trebuchet\" egységeket",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Az AI-stratéga nem változtatja folyton a parancsokat és nem spammel hanggal; a harcok melletted zajlanak; B — átdobás, Shift+B — a harc sűrűjébe; iránytű, H — melyik cél",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Szabad játék (K) és egyedül játszom (J), F2 — előbeállítások; Esc szüneteltet és folytat; mentések: helyek, exportálás és importálás",
"New in v5.3":"Újdonságok a v5.3-ban",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Repülés: erősebb gravitáció a meteortól távol, C a levegőben fékez, a tolóerő élesebben kormányoz; többé nem akadsz el a portálban",
"New in v5":"Újdonságok a v5-ben",
