"Guides you during play: arrows to buttons and marks on the map. Turn it off any time (also in Settings).":"Játék közben súg: nyilak a gombokhoz és jelölések a térképen. Bármikor kikapcsolhatod (a Beállításokban is).",
"queue {0}/5":"sor {0}/5",
"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"Jelöld ki a főhadiszállást, és rendelj mérnököt (50 érc) — a kattintás megnyitja a főhadiszállás panelét",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"Mérnököt csak a főhadiszálláson lehet rendelni: jelöld ki a főhadiszállást (kattints rá vagy F2) — jobbra megnyílik a gyártópanelje. Ugyanez a mechgyárnál, drónközpontnál, légikikötőnél és előőrsnél",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"Az Építés fül akkor nyílik meg, ha mérnök van kijelölve; van „Legközelebbi mérnök kijelölése\" gomb; a Z X C V B N K billentyűk automatikusan mérnököt választanak",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"A Kalauz a stratégiai oktatás helyett van: játék közben javasolja, mit tegyél, nyíllal mutatja a gombot és jelölést tesz a térképre; a panelen vagy a Beállításokban kikapcsolható",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"Fejlesztői mód (főmenü): végtelen érc, minden feloldva, azonnali építés, az Arzenál — bármely fegyver, osztály, jármű, céltábla-bábuk; a karriered érintetlen marad",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"Telefon: a lövész gombok nem takarják a célkeresztet és a fegyvert, a stratégiai panelek összecsukódnak, nagyobb gombok, érthető „Stratégia ⇄ Harc\" váltó",
"Combined build: the v6.2 ore-vein crystals and extractors + grenades with a throw arc":"Összevont kiadás: a v6.2 érceres kristályai és kitermelői + gránátok dobási ívvel",
"New in v6.4":"Újdonságok a v6.4-ben",
"Curator on: I will suggest what to do":"Kalauz bekapcsolva: javaslatokat teszek, mit tegyél",
"Curator off (turn on with the \"Curator\" button or in Settings)":"Kalauz kikapcsolva (bekapcsolás: „Kalauz\" gomb vagy Beállítások)",
