"Select a builder: \"⚒ Select nearest builder\" on the right or click one.":"Jelölj ki egy mérnököt: a „⚒ Legközelebbi mérnök kijelölése\" gomb jobbra, vagy kattints rá.",
"Tap the marked vein ⛏ (glowing crystals), then \"✔ Build\". Mark off-screen — tap it to fly the camera there.":"Koppints a jelölt érre ⛏ (világító kristályok), majd „✔ Építés\". A jelölés a képernyőn kívül van — koppints rá, a kamera odarepül.",
"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"Kattints a jelölt érre ⛏ — a világító kristályokra (jobb egérgomb/Esc — mégse). A jelölés a képernyőn kívül van — kattints rá, a kamera odarepül.",
"Tap a spot for the {0}, then \"✔ Build\".":"Koppints egy helyre: {0}, majd „✔ Építés\".",
