"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"Én vagyok a Kalauz: kiemelem a megfelelő gombot és a helyet a térképen. A „✕\" kikapcsol.",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"Én vagyok a Kalauz. Játék közben súgok, mit tegyél: kiemelem a gombot és a helyet a térképen. Kikapcsolás: itt a „✕\" vagy a „Kalauz\" gomb jobbra lent.",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"A Raj a bázisnál van! „Teljes sereg\", majd hosszú koppintás az ellenségekre. A bázisnál álló torony is segít.",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"A Raj a bázisnál van! Jelöld ki a csapatokat (kerettel vagy Ctrl+A), és jobb egérgomb az ellenségekre. A bázisnál álló torony (Z) is segít.",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"Kamera: húzd a térképet egy ujjal, két ujjal — nagyítás és forgatás. Told el a kamerát.",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"Kamera: WASD vagy a képernyő szélei, görgő — magasság, Q/E — forgatás. Told el a kamerát.",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"Nincs mérnök — nélkülük semmi sem épül. Jelöld ki a főhadiszállást — kattints rá vagy a „⌂ Főhadiszállás\" gombra.",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"Rendelj mérnököt — a „⚒ Mérnök\" gomb a főhadiszállás panelén (50 érc).",
"We need ore — let us put an extractor on an ore vein.":"Érc kell — tegyünk egy kitermelőt egy ércerezre.",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"Nyomd meg a „Kitermelő\" gombot (C), és tedd az ér világító kristályaira — megjelöltem ⛏.",
"Few troops. Select the HQ — squads are ordered there.":"Kevés a csapat. Jelöld ki a főhadiszállást — ott rendelhetsz osztagokat.",
"Order an \"Assault squad\" in the HQ panel.":"Rendelj „Rohamosztagot\" a főhadiszállás panelén.",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"A pontok ércet adnak. Jelölj ki egy osztagot — koppints rá vagy a „◈ Osztag\" gombra jobbra.",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"A pontok ércet adnak. Jelölj ki egy osztagot — koppints rá vagy a „◆ Sereg\" kártyára fent.",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"A pontok ércet adnak. Jelölj ki egy osztagot — kattints rá vagy a kártyájára a „◆ Sereg\" panelen balra.",
"Long-tap point {0} — the squad goes to capture it.":"Hosszú koppintás a(z) {0} pontra — az osztag elindul elfoglalni.",
"RMB on point {0} — the squad goes to capture it.":"Jobb egérgomb a(z) {0} pontra — az osztag elindul elfoglalni.",
"POINT ":"PONT ",
"The base is under attack — let us build a turret.":"Megtámadják a bázist — építsünk tornyot.",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"Nyomd meg a „Torony\" gombot (Z), és tedd a bázisnál az ellenség felőli oldalra.",
"Enough ore for a mech factory — it makes tanks and vehicles.":"Elég az érc egy mechgyárra — harckocsikat és járműveket gyárt.",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"Nyomd meg a „Mechgyár\" gombot (B), és tedd a bázisra (sík hely a szaggatott körön belül).",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0} tétlen — jelöld ki, és adj parancsot: {1} egy pontra vagy ellenségre.",
"The mech factory is ready. Select it to order a tank.":"A mechgyár kész. Jelöld ki — rendeljünk harckocsit.",
"Order a \"Tank\" in the factory panel.":"Rendelj „Harckocsit\" a gyár panelén.",
"More extractors — more ore. There is a free vein nearby.":"Több kitermelő — több érc. Közelben van egy szabad ér.",
"\"Extractor\" (C) on the marked vein ⛏.":"„Kitermelő\" (C) a megjelölt érre ⛏.",
"Pick a power and click an enemy cluster.":"Válassz csapást, és kattints ellenséges csoportosulásra.",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"Gyűlnek a parancsnoki pontok — a „✺ Csapások\" fül: tüzérségi csapás, felderítés, ledobókapszula.",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"Kevés az érc? Koppints az „ÉRC\"-re fent — megmutatom, honnan jön a bevétel és hogyan növelheted.",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"Szeretnél magad harcolni? Jelölj ki egy osztagot, és nyomd meg az „▶ Átvétel\" gombot.",
