"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Koppints a „Célzás” gombra a nagyításhoz. Még egy koppintás — vissza.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Az osztagod követ téged. Nyisd meg a ☰ → „Szünet” → az „Osztag velem” csempe — „Egyedül cselekszem” lesz belőle.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"A mérnök ki van jelölve — koppints a „◆ Kristálybányászat” gombra a kártyáján lent (vagy a zöld kristályokra).",
"Training complete!":"Gyakorlás kész!",
"steps":"lépés",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Tudsz bázist építeni, csapatokat rendelni, parancsnokolni és csatába ugrani. Következik egy igazi meccs: a Kalauz a játék közben segít.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Tudsz mozogni, repülni, lőni, fedezékbe húzódni és az osztagodat irányítani. Következik egy igazi csata.",
"Real battle":"Igazi csata",
"Again":"Még egyszer",
"done":"kész",
"you are on PC: keyboard and mouse":"PC-n vagy: billentyűzet és egér",
"you are on a phone: touch screen":"Telefonon vagy: érintőképernyő",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Biztonságos gyakorlótér: az ellenfelek mozdulatlan bábuk, senki sem lő rád. A lépés csak akkor számít, ha tényleg megcsinálod a műveletet.",
"Show others (training for the other device)":"Mások megjelenítése (gyakorlás a másik eszközre)",
"Old training (v7.1)":"Régi gyakorlás (v7.1)",
"Back to the normal device mode":"Vissza a szokásos eszközmódhoz",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"A másik eszköz gyakorlása újraindítja az oldalt annak módjában (PC — egér és billentyűzet, telefon — érintés; PC-n az érintést Chrome-ban tesztelheted: F12 → telefon ikon).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Gyakorlás ×4: külön lépésenkénti „Stratégia” és „Lövész” leckék PC-re és telefonra. Biztonságos homokozó bábukkal, kiemelt gombok, nyilak, animált billentyűk, egér és gesztusok; egy lépés csak valódi cselekvésre számít, „lépés ismétlése”, haladás felül és jutalom a végén",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"A Gyakorlás menü az eszközödhöz tartozó leckéket mutatja; a „Mások megjelenítése” bármely eszközön mind a négyet; a „Régi gyakorlás (v7.1)” megmaradt",
"New in v7.2":"Újdonságok a v7.2-ben",
"NEW IN v7.2":"ÚJ A v7.2-BEN",
"No grenades left":"Elfogytak a gránátok",
"Rocket and grenade recharging · {0} s":"Rakéta és gránát töltődik · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Balra — mozgás, jobbra — nézelődés · koppints az ellenségre — rakéta / gránát · 2 koppintás — reflex · 3 koppintás — tüzérségi csapás",
"Less":"Kevesebb",
"More":"Több",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Ellenséges jármű vagy építmény van a közelben — koppints rá: rakéta indul.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Sok az ellenség — koppints kétszer egy üres helyre jobbra: a reflex lelassítja az időt.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Célozz az ellenség csoportjára és koppints 3-szor — tüzérségi csapás.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Bal hüvelykujj — mozgás, jobb — nézelődés. Ha a célkereszt az ellenségen van, magától lő.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ a bal szélen — jetpack: koppintásra ugrasz, nyomva tartva repülsz.",
"Old v7.2 layout":"Régi v7.2 elrendezés",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Húzd az ujjad a képernyő jobb felén — alatta megjelenik a nézelődő kar.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Érintsd meg a bal oldalt és húzd az ujjad — alatta megjelenik a kar. Menj a zöld jelölőig.",
"Hold the \"Jet\" button at the left edge.":"Tartsd nyomva a „Jet” gombot a bal szélen.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"A jobb karral célozz a bábura — a katona magától lő, ha a célkereszt rajta van.",
"Tap the dummy on the screen — a rocket flies.":"Koppints a bábura a képernyőn — rakéta indul.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Koppints a bábura — gránát repül ívben, egyenesen rá.",
"Double tap an empty spot on the right quickly.":"Gyorsan koppints kétszer egy üres helyre jobbra.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Könnyű mód gyenge telefonokhoz: kisebb felbontás, nincs árnyék és torzítás, feleannyi bot és részecske, legfeljebb 30 FPS; magától csökkenti a felbontást, ha az FPS < 25. Telefonon alapból be van kapcsolva (Beállítások → Grafika → „Könnyű mód”; vagy ?lite=1 / ?lite=0 a linkben).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: új irányítás. Balra — mozgás, jobbra — nézelődés (mindkét kar az ujjad alatt jelenik meg). Csak a bal ujj — „auto”; ha a jobb is dolgozik, a katona csak akkor lő magától, ha a célkereszt az ellenségen van. Koppintás az ellenségre — rakéta vagy gránát, 2 koppintás — reflex, 3 koppintás — tüzérségi csapás. Automatikus újratöltés. Jetpack — gomb a bal szélen. Az alsó sarkok szabadok, a minitérkép a sarokban van, a tippek kereszttel bezárhatók, a feladat összecsukható. Régi elrendezés: Beállítások → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Tippek (felugró és Kurátor) — egy kapcsoló a beállításokban. Kit irányítasz (egység vagy jármű típusa) — „Te: …” felirat a HUD-on. A puska és a géppuska optikája átlátszó. Az „Arzenál” panel jobbra van rögzítve, összecsukható és kikapcsolható. Az „egyedül osztag nélkül” mód (J) megszűnt. A stratéga hangja nem ismétli ugyanazt egymás után. A harckocsiknál van torony–páncéltest jelző. A kurzor már nem tűnik el a stratégia-gyakorlás elején.",
