"Voice of hints & curator":"Tippek és Kurátor hangja",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: három karmód. Csak bal — „auto” (erős mágnes, gyengébb lövedékek). Csak jobb — a célzás magától bekapcsol, erősebb mágnes, pontosabb lövés. Mindkettő — nincs célzás, gyengébb mágnes és pontosság. A jobb oldali 👁 gomb elrejti/visszahozza a kezelőfelületet.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: egyszerűsített stratégia — csak építőmérnök és épületek. Balra kártyák (építőmérnök, HQ, laktanya…): koppintásra a kamera odarepül, alul látszik, mit építhetsz/gyárthatsz. „Harcba” — balra fent. A sereg magától harcol. Teljes stratégia — Beállítások → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Birtokbavétel — két jelölőnégyzet: „Osztagok” és „Járművek” (telefonon a járművek alapból ki vannak kapcsolva — az MI vezeti őket). Ha a járművek ki vannak kapcsolva, E (telefonon a jobb oldali gomb) egy baráti jármű mellett — foglald el a lövegét: a jármű magától megy, te lősz. A régi egyedi osztálysorrend a „Haladó” alatt van. Átvételkor az egység rádión válaszol.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Okos tippek: az alaptippek a 2. indítás után maguktól kikapcsolnak, de a játék rámutat arra a funkcióra, amit sosem használsz. Kapcsolók: alap / haladó / ritka, külön a tippek és a Kurátor hangjára.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"A reflex ölésekből töltődik (a sorozat jobban tölt). A társak lemaradtak vagy elestek — az MI-stratéga újakat dob le hozzád (drágább a szokásos erősítésnél). A v7.2gfx grafika és hang beépült: gomolygó robbanások, füst, törmelék, aknák és kráterek akusztikája. A build dátuma már valódi.",
