"both bases built and upgraded — for footage":"mindkét bázis felépítve és fejlesztve — forgatáshoz",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mozi mód — osztott képernyő: balra a stratégabot (felülnézet a bázisról és a seregről), jobbra a lövészbot első személyben. Gombok alul (és az S, P billentyűk): „Osztott képernyő” és „★ Minden felépítve” — mindkét bázis felépítve és fejlesztve a forgatáshoz.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"A mag és az alagutak a meteoron át megszűntek — a meteor tömör, a harc csak a felszínen zajlik.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: a 👁 elrejti a kezelőfelületet, de meghagyja a repülőcsomagot, a ⇆-t, a karokat és a feladatjelölőt. A „◎ Célzás\" (csak a jobb ujjal) — jóval erősebb és szélesebb mágnes; a mágnes erőssége mindhárom módhoz: Beállítások → Irányítás → „Haladó\". Járműágyúnál a gomb neve „Leszállás\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Gyakorlás: telefonon csak a telefonos, PC-n csak a PC-s leckék látszanak. Mind a 4 a „🛠 Fejlesztő\" menüben van. A fejlesztői mód és az Arzenál egy menüvé olvadt (csatában — „🛠 Menü\" jobb felül, PC-n F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"A „Dendy (8 bites)\" és a „16 bites\" grafikai stílus: Beállítások → Grafika → „Grafikai stílus\" (részletek — a ⚙ gomb). Ha a meccs első ~10 másodpercében az FPS 24 alatt van, a Dendy magától bekapcsol (20 alatt még nagyobb pixelekkel, 120 sor); a „vissza a normálhoz\" értesítés végleg visszaállítja a normál grafikát. A menüben megadott saját választásod mindig előnyt élvez.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D környezeti modellek (romok, roncsok, erődítmények) — csak a jól értékeltek, igény szerint töltődnek be. Kikapcsolás: Beállítások → Grafika → „Új 3D környezeti modellek\".",
