"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Építés harcosokkal: E (telefonon „Belépés\") a saját építkezésnél — a harcosod maga épít, a közeli bajtársak segítenek. Ha a mérnökök elfoglaltak, a stratéga maga kér segítséget — „ÉPÍTKEZÉS\" jelölővel.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Stratéga jelölései: a stratéga ⌖-t tesz egy közeli ellenséges csoportosulásra — 8 s múlva tüzérség csap oda, a közeli saját „Grad\" sorozatvetők pedig sortüzet adnak. A stratégiamódból indított saját tüzérségi csapásodat is támogatják a „Gradok\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Fegyver-rejtekhelyek teherkonténerekben és lezuhant műholdakban (a 📦 70 m-ről látszik): E — nehézgéppuska 90 s-ig, gyújtólövedékek vagy rakéták, plusz teli gránáttár. Kúszás: Ctrl — lefekvés / felállás (alacsonyabb, stabilabb célzás, de lassú).",
