"Link copied":"Link kimásolva",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Játék most\" — a menü első gombja: rövid átrepülés a portálégbolt alatt, és rögtön csatában vagy (átugrás — bármelyik billentyű vagy koppintás).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"A találatok érződnek: fémes hang és szikrák, kiiktatásjelző a célkeresztnél (fejlövés — sárga), ×N sorozat, finom rázkódás a robbanásoktól, lassított felvétel a fontos kiiktatásoknál. A rázkódás, a lassítás és a tipp kikapcsolható a Beállításokban.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Meccseredmény: idő, kiiktatások, legjobb sorozat, ★ MVP és legjobb osztag, meccskártya — „⇪ Megosztás\", PNG vagy link a játékhoz.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"„Mit tegyél most\" tipp balra az erőforrások alatt: a stratéga parancsa, elfoglalandó pont, a Raj támadása. ✕ vagy F7 — összecsukás.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"A csata magától mentődik, ha bezárod vagy elrejted a lapot — „⟲ Folytatás\" a menüben.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"A v7.5 megmarad a „🕘 Játékverzió\" menüben, ha jobban szereted. Mostantól névtelen statisztika (név és e-mail nélkül) kerül elküldésre; kikapcsolás — a Beállításokban.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Játék most\", találatvisszajelzés, meccseredmény megosztható kártyával, „mit tegyél\" tipp, automentés",
"and older: v7.5, v7.4, milestones v1–v7.0":"és régebbiek: v7.5, v7.4, v1–v7.0 mérföldkövek",
"New in v7.6":"Újdonságok a v7.6-ban",
"NEW IN v7.6":"ÚJDONSÁGOK A v7.6-BAN",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Frakcióválasztás a meccs előtt: a „Konzorcium\" (nehéz, energiapáncélos gyalogság, páncél és tüzérség) vagy a „Raj\" (sebesség, drónrajok, nehéz lövések torzítással). A másikat az MI játssza. A választás megmarad.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Minden frakciónak saját járművei és egyedi képességei vannak: a Konzorciumnak a „Rhino\" harckocsi és a „Keramit lemezek\", a Rajnak a „Drónraj\" és a „Fázis repülőcsomagok\". Az egyensúlyt botmeccsekkel ellenőriztük.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Robbanáskráterek: a tüzérség, a rakéták és a harckocsiágyúk gödröket ásnak a meteorba — át lehet rajtuk menni és hajtani, és fedezéket lehet venni bennük.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Harmadik személyű nézet a katonáknak (V, megjegyzi; telefonon — Irányítás) és sima járműkamera jelzéssel, hová csapódik az ágyúlövés.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"A v7.6 megmaradt a „🕘 Játékverzió” menüben, ha úgy jobban tetszik.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Konzorcium / Raj frakciók meccs előtti választással, robbanáskráterek, harmadik személyű nézet",
"and older: v7.6, v7.5, milestones v1–v7.0":"és régebbiek: v7.6, v7.5, mérföldkövek v1–v7.0",
