"Hear that hum? A singing vein. Keep clear!":"Hallod ezt a zúgást? Éneklő ér. Ne menj közel!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomália! Kavarog a levegő — ez egy örvény, kerüld ki!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kövek lebegnek a levegőben… Örvény! Ne menj bele!",
"Anomaly ahead — it is crackling with current!":"Anomália előttünk — recseg az áramtól!",
"Rods and lightning — a Crackler. It loves armour!":"Rudak és villámok — Recsegő. A páncélt szereti!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomália! Remeg a föld a hőségtől — Parázstál!",
"Careful, a Brazier underfoot!":"Óvatosan, Parázstál van a lábad alatt!",
"Anomaly — green mist! Acid, hold your breath!":"Anomália — zöld köd! Sav, ne lélegezz!",
"The mist is drifting our way, go around!":"A köd felénk kúszik, kerüljük ki!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomália! A levegő olyan, mint az üveg — Lencse, elhajlítja a golyókat!",
"Everything is warping… a Lens nearby!":"Minden torzul… Lencse van a közelben!",
"Ha! An enemy walked right into the anomaly!":"Ha! Az ellenség egyenesen az anomáliába lépett!",
"Got him! Lure them into anomalies!":"Megvan! Csalogasd őket az anomáliákba!",
"Beautiful zap! One less tin can.":"Szép durranás! Eggyel kevesebb vasdoboz.",
