"Supply drop":"Utánpótlásláda",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Ládát dob le az erőid közelébe: lőszer, gránátok, rakéták, fegyveralkatrészek, javítókészlet.",
"\"Grad\" rocket strike":"„Grad” rakétacsapás",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"3 másodperc múlva 16 rakéta nagy területre — gyorsabb és szélesebb a tüzérségi csapásnál.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Támogatás: láda, felderítés, „Grad”, tüzérségi csapás (utána 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"FIGYELEM: a Raj „Gradja” csap le a térségedre!",
"Warning! Rocket salvo on our position!":"Figyelem! Rakétasortűz a pozíciónkra!",
"take the supply crate":"utánpótlásláda felvétele",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomáliák a meteoron (1. hullám): az „Éneklő Ér” — izzó zöld kristály, zúg, és ritmikus impulzusokkal sújt le mindenkire a közelben; az „Örvény” húz és odacsap, a „Recsegő” íveket húz a rudak között, a „Parázstál” lángra lobban a lábad alatt, a „Savköd” és a „Lencse” (elhajlítja a golyókat és a képet) sodródnak.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Az anomáliákat előre érezni (zúgás, fény, hőpára). Kisüthető gránáttal, rakétával vagy csavarral (E mellette): elszunnyad, néha műtárgyat hagy hátra előnnyel és hátránnyal. Az osztag rádión figyelmeztet, az ellenségek (és a sajátjaink) néha beletévednek — csalogasd őket!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Támogatás PP-ért: 4 van csatában (telefonon 📡) — utánpótlásláda, felderítő pásztázás, „Grad” rakétacsapás, tüzérségi csapás a célkeresztnél. A stratéga csak pásztázás után látja az anomáliákat a térképen.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Utánpótlásládák régi expedíciók romjaiban, a főhadiszállások mellett és az elkészült épületeknél: lőszer, gránátok, rakéták, fegyveralkatrészek (ezek feloldják a kiegészítőket).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"A v7.7 megmaradt a „🕘 Játékverzió” menüben. Az anomáliák kikapcsolhatók a Beállításokban.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomáliák (az „Éneklő Ér” és még 5), kisütés csavarral és gránáttal, műtárgyak, támogatás PP-ért, utánpótlásládák",
"and older: v7.7, v7.6, milestones v1–v7.0":"és régebbiek: v7.7, v7.6, mérföldkövek v1–v7.0",
"New in v7.8":"Újdonságok a v7.8-ban",
"NEW IN v7.8":"ÚJ A v7.8-BAN",
"Close":"Bezárás",
"Anomalies on the meteor":"Anomáliák a meteoron",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"A sarokban lévő ☰ megnyitja a szünet menüt: Folytatás, Újrakezdés, Gyakorlás, Grafika, Beállítások, Főmenü (megerősítéssel). Telefon: ☰ jobbra fent (csatacselekvések — a „⚡ Műveletek” csempe); PC: a „☰ Menü” gomb jobbra fent vagy Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"A grafika alapból mindig normál — a Dendy csak ha te választod: a „Grafika: Normál / Dendy (8 bites) / 16 bites” kapcsoló a főmenüben és a szünet menüben van. Ha a játék nagyon lassú, megjelenik egy tipp a „Dendy bekapcsolása” gombbal.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon és tablet: a jobbra lévő „✋” műveletgomb csak akkor jelenik meg, ha van a közelben tennivaló — „Felvétel” (rejtekhely, láda), „Beszállás” (jármű, lövegtorony, löveg), „Építés”, „Leszállás”, „Csavar” anomáliánál. Elég a kiemelt tárgyra koppintani is.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, stratégia: tartsd az ujjad ~0,3 s-ig (a telefon rezeg, sárga gyűrű jelenik meg), majd húzd — kijelölő keret; a sima húzás mozgatja a kamerát. Van „Keret” gomb is jobbra; a gyakorlásban a „Keret” lépést az osztagra koppintás is teljesíti.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: az apró gombokat könnyebb eltalálni, a 📡 támogatási lista nagyobb, a stratégiai panelek már nem takarják a szünet és az eredmény képernyőt. A v7.8 megmaradt a „🕘 Játékverzió” menüben.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"☰ menü telefonon és PC-n, nincs automatikus Dendy, „✋” gomb érintőképernyőn, keretes kijelölés telefonon",
"16-bit":"16 bites",
"Lagging? Try the Dendy graphics — they are lighter.":"Laggol? Próbáld a Dendy grafikát — könnyebb.",
