"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Tartsd az ujjad a talajon ~0,3 s-ig — a telefon rezeg, és sárga gyűrű jelenik meg — majd felemelés nélkül húzd: keret jelenik meg. Vagy használd a „Keret” gombot jobbra. Az osztagra koppintás is működik.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Teljes képernyőhöz iPhone-on: „Megosztás” ⬆ → „Főképernyőhöz adás” — a játék a Safari sávjai nélkül nyílik meg.",
"Open portal-meteor.pages.dev for that.":"Ehhez nyisd meg a portal-meteor.pages.dev oldalt.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Koppintás — kijelölés · koppintás a talajra — mozgás · tartás — parancsmenü · tartás és húzás — keret · 2 ujj — nagyítás",
"Robo-ninja":"Robotnindzsa",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Bérgyilkos hős: villanó rohamok, katana, shurikenek. Magától ugrál az ellenséges zónák között, és darabokra vágja a robotokat. Oldalanként 1.",
"Shadow protocol":"„Árnyék” protokoll",
