"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Hős (oldalanként 1): magától teleportál az ellenséges zónák között, és darabokra vágja a robotokat; át is veheted, és kézzel játszhatsz vele.",
