"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: magától ugrál az ellenséges zónák között és vág. Joystick / WASD — 1.5 s szünet",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Kézi: koppints az ellenségre — roham és vágás, húzás — suhintás, 🛡 — blokk",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Kézi irányítás: bal egérgomb — katana, jobb egérgomb — blokk, Shift — roham, Q — shurikenek, G — teleport",
