"Radio: start by itself in battle":"Rádió: induljon magától harcban",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: kiborg katanával. A Laktanyában az „Árnyék protokoll” kutatással nyílik meg (Mechgyár kell hozzá). Magától teleportál az ellenséges zónákba, darabokra vágja az ellenfeleket (vér helyett szikrák), rohan, shurikeneket dob, párbajozik az ellenséges ninjával. Vedd át az irányítást — AUTO mód vagy kézi vezérlés (telefonon saját gombokkal).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor Rádió: 103 EDMITRY-szám közvetlenül a játékban. 5-ös billentyű (átállítható), telefonon — ☰ → Beállítások → Hang. A hangerő és a „induljon magától harcban” a beállításokban; a zene halkul robbanásoknál és a rádióhang alatt.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Új nyelvek: üzbég és tadzsik — teljes; kínai, spanyol, portugál — részleges. Új nyelvválasztó a menüben az „Új meccs” mellett.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: a „ikonok elrejtése” 👁 a megmaradt gombokat rendezett oszlopba gyűjti a jobb szélen; az álló nézet már nem csúszik egymásra; iPhone — a játék nem ütközik a Safari kézmozdulataival, a „Megosztás → Főképernyőhöz adás” pedig teljes képernyőn indítja.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"A v7.8.1-ből: ☰ sarokmenü (szünet, újraindítás, gyakorlás, grafika), nincs automatikus Dendy, ✋ akciógomb telefonon. A v7.8.1 és v7.8 a „🕘 Játékverzió” menüben marad.",
