"⚠ WARNING: the enemy {0} is on the battlefield!":"⚠ FIGYELEM: az ellenség {0}-ja megjelent a csatatéren!",
"Warning! The enemy {0} is on the field!":"Figyelem! Az ellenség {0}-ja a csatatéren van!",
