"MY SQUADS":"OSZTAGAIM",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"A veterán státusz csatáról csatára megmarad. Az osztag tapasztalatot gyűjt (gyalogság 1, épület 2, jármű 3), szintet lép, csillagokat és képességeket kap. Új csatában a veteránok vonulnak be elsőként. Az elveszett osztag mindent elveszít, és az Elesettek közé kerül.",
