"No losses.":"Nincs veszteség.",
"My squads":"Osztagaim",
"active":"aktív",
"campaign":"hadjárat",
"\"Commander\" mode on phone":"Parancsnok mód telefonon",
"Smoke grenades":"Füstgránátok",
"A screen at a point for 14 s — enemies cannot see through.":"14 mp-re füstfüggöny a megadott ponton — az ellenség nem lát át rajta.",
"Flank sprint":"Szárnyroham",
"Run to a point at ×1.6 speed without stopping to fight (7 s).":"Futás a pontra ×1,6 sebességgel, harcba bocsátkozás nélkül (7 mp).",
"Suppressing fire":"Fedezőtűz",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"Záporozó tűz 14 m-es területre: az ellenség lelassul és mellélő (7 mp).",
"Field medic":"Tábori szanitéc",
"+20% hull to all at once, then 4 s of repair.":"Azonnal +20% páncélzat mindenkinek, utána még 4 mp javítás.",
"Regen burst":"Regenerációs lökés",
"Swarm: 8 s of fast regeneration for the whole squad.":"Raj: 8 mp gyors regeneráció az egész osztagnak.",
"Grenade volley":"Gránátsorozat",
"Every trooper throws a grenade at the point.":"Minden baka gránátot dob a pontra.",
"AT rocket":"Páncéltörő rakéta",
"Heavy rockets at a vehicle or building (up to 3).":"Nehéz rakéták járműre vagy épületre (legfeljebb 3).",
"Mini barrier":"Mini akadály",
"Consortium: a concrete section in front of the squad for 40 s.":"Konzorcium: betonszelvény az osztag előtt 40 mp-re.",
"No squads to command — order a squad":"Nincs parancsolható osztag — rendelj egyet",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"Parancsnok: {0}. bal egérgomb — mozgás / támadás, 1–4 — képességek, Tab — másik osztag, dupla kattintás egy bakára — harc, P — stratégia",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"Koppintás — mozgás/támadás, dupla koppintás egy bakára — harc, jobb oldali gombok — képességek",
"Commanding: {0}":"Parancsnoklás: {0}",
"cooling down":"újratöltés",
