"Living world":"Élő világ",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"A tieid segítséget kérnek és megjutalmaznak, a hősök küldetést adnak, a megrekedt frontot egy áttörő művelet töri meg",
"A request":"Kérés a sajátoktól",
"Breakthrough":"Áttörés",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"A tieid néha segítséget kérnek: hang a rádión, „KÉRÉS\" kártya és ✋ jelölő. Egy osztagot leszögeztek — semmisítsd meg a közelében lévő ellenséget. Jutalom: katona kapszulával az alapról, fegyver egy bugi csomagteréből, a lövész helye vagy orbitális fedezék. Nem akarod — ✕ vagy egyszerűen hagyd figyelmen kívül.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"A veterán felderítő, „Bagoly\" küldetést ajánl. Y — elfogad (N — elutasít). Menj a ★ jelölőhöz, szedd le az őrséget, és állj a pilóta mellett 3 s-ig — csatlakozik az osztagodhoz.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"A front megrekedt — a HQ áttörést ajánl. Y — elfogad. Tartsd az átjátszót 8 s-ig ellenség nélkül: az ellenség térképe 60 s-ig látszik. A generátor — az ellenséges tornyok 2 percig hallgatnak. Stratéga módban — „Kiadás osztagnak\". Az ellenség is tudja ezt: figyeld a ⚠-t.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"A tieid segítséget kérnek: „KÉRÉS\" kártya és ✋ jelölő. Semmisítsd meg a leszögezett osztag közelében lévő ellenséget — jutalmat kapsz. ✕ — kihagyás.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"A „Bagoly\" hős küldetést ajánl — koppints az „Elfogad\" gombra. Menj a ★-hoz, szedd le az őrséget, állj a pilóta mellett.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"A front megrekedt — koppints az „Elfogad\" gombra, és tartsd az átjátszót 8 s-ig: az ellenség térképe egy percre megnyílik.",
