"Launch pad":"Kilövőpad",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Akna a főhadiszállás mellett: innen indulnak a kapszulák, utánpótlás-ládák és bombázók az égi portálon át a célhoz. Építeni rá nem lehet.",
"Economy":"Gazdaság",
"Key building":"Kulcsépület",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Gyenge pont — a hátulja (motor): sebzés ×{0}. Ágyú, 2 géppuskatorony, rakétakazetta; nagyon lassan fordul — kerüld meg oldalról.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Gyenge pont — a hasa alatti izzó mag: alulról ×{0} sebzés. Torzító sugár és területi tapodás; átlépi az akadályokat — tartsd a távolságot, ne álljatok csomóban.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Ellene: légibombák és tüzérség (×{0}), rakéták (×{1}), szőnyegbombázás; a golyók alig sebzik (×{2}).",
"Faction":"Frakció",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Gyors gépek, drónrajok, alagutak és regeneráció. Könnyebb, de gyorsabb gyalogság; az ágyúk és sínágyúk erősebben ütnek.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Nehéz, erőpáncélos gyalogság, betonakadályok, javítás és tüzérség. Lassabb, de szívósabb.",
